package org.planqk.atlas.web.linkassembler;

import java.util.UUID;

import org.planqk.atlas.web.Constants;
import org.planqk.atlas.web.controller.DiscussionTopicController;
import org.planqk.atlas.web.dtos.DiscussionTopicDto;

import org.springframework.hateoas.EntityModel;
import org.springframework.stereotype.Component;

import static org.springframework.hateoas.server.mvc.WebMvcLinkBuilder.methodOn;

@Component
public class DiscussionTopicAssembler extends GenericLinkAssembler<DiscussionTopicDto> {

    @Override
    public void addLinks(EntityModel<DiscussionTopicDto> resource) {
        resource.add(links.linkTo(methodOn(DiscussionTopicController.class).getDiscussionTopic(this.getID(resource))).withSelfRel());
        resource.add(links.linkTo(methodOn(DiscussionTopicController.class).getDiscussionComments(this.getID(resource), 0, 20)).withRel(Constants.DISCUSSION_COMMENTS));
    }

package org.planqk.atlas.web.linkassembler;

import java.util.UUID;

import org.planqk.atlas.web.controller.DiscussionTopicController;
import org.planqk.atlas.web.dtos.DiscussionCommentDto;

import org.springframework.hateoas.EntityModel;
import org.springframework.stereotype.Component;

import static org.springframework.hateoas.server.mvc.WebMvcLinkBuilder.methodOn;

@Component
public class DiscussionCommentAssembler extends GenericLinkAssembler<DiscussionCommentDto> {

    @Override
    public void addLinks(EntityModel<DiscussionCommentDto> resource) {
        resource.add(links.linkTo(methodOn(DiscussionTopicController.class).getDiscussionComment(getTopicId(resource), getID(resource))).withSelfRel());
    }

    private UUID getID(EntityModel<DiscussionCommentDto> resource) {
        return resource.getContent().getId();
    }

    public UUID getTopicId(EntityModel<DiscussionCommentDto> resource) {
        return resource.getContent().getDiscussionTopic().getId();
    }
}
