 keyboard shortcuts 
    // cross browser compatibility https://medium.com/@uistephen/keyboardevent-key-for-cross-browser-key-press-check-61dbad0a067a
    document.onkeydown = (evt) =>{
      // Escape key
      if(evt.keyCode === 27){
        this.playMedia();
