jobs:
  pre-checks:
    name: Check if job should run
    runs-on: ubuntu-20.04
    env:
      CREATE_PATTERNS: ^release/,^hotfix/
    outputs:
      GIT_BRANCH: ${{ steps.git-branch.outputs.GIT_BRANCH }}
      PRE_CHECK_OK: ${{ steps.branch-name-check.outputs.PRE_CHECK_OK }}
    steps:
      - name: Get git branch
